Your expense tracker is below. Add an item with amount, category and date, and it totals the month and splits it by category. Entries stay only while this page is open, so note down your totals before you close it.

```page
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Monthly expenses</title>
<style>
  body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f6f7f9;color:#1c1f24}
  h1{font-size:18px;margin:0 0 12px}
  .card{background:#fff;border-radius:12px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
  .row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
  input,select,button{font:inherit;padding:8px;border:1px solid #cfd4dc;border-radius:8px;background:#fff}
  input.grow{flex:1;min-width:120px}
  input.amt{width:110px}
  button{cursor:pointer}
  button.primary{background:#2563eb;color:#fff;border-color:#2563eb}
  .total{font-size:26px;font-weight:600;margin:4px 0}
  .muted{color:#6b7280;font-size:13px}
  .bar{height:8px;background:#e5e7eb;border-radius:4px;overflow:hidden;margin:3px 0 8px}
  .bar>div{height:100%;background:#2563eb}
  .cat{display:flex;justify-content:space-between;font-size:14px}
  .item{display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-top:1px solid #eef0f3}
  .item:first-child{border-top:0}
  .x{border:0;background:none;color:#b91c1c;padding:4px 8px}
</style>
</head>
<body>
<h1>Monthly expenses</h1>

<div class="card">
  <div class="row">
    <input id="desc" class="grow" placeholder="What was it for?">
    <input id="amt" class="amt" type="number" min="0" step="any" placeholder="₹ Amount">
  </div>
  <div class="row" style="margin-top:8px">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <input id="date" type="date">
    <button class="primary" id="add">Add</button>
  </div>
  <div class="muted" id="msg" style="margin-top:6px"></div>
</div>

<div class="card">
  <div class="row" style="justify-content:space-between">
    <span class="muted">Month</span>
    <input id="month" type="month">
  </div>
  <div class="total" id="total">₹0</div>
  <div class="muted" id="count"></div>
</div>

<div class="card"><div id="cats"></div></div>
<div class="card"><div id="list"></div></div>

<script>
(function(){
  var items=[];
  var $=function(id){return document.getElementById(id)};
  var today=new Date().toISOString().slice(0,10);
  $('date').value=today;
  $('month').value=today.slice(0,7);

  try{var saved=localStorage.getItem('exp');if(saved)items=JSON.parse(saved)||[]}catch(e){}
  function save(){try{localStorage.setItem('exp',JSON.stringify(items))}catch(e){}}

  function inr(n){return '₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:2})}
  function esc(s){var d=document.createElement('div');d.textContent=s;return d.innerHTML}

  function add(){
    var a=parseFloat($('amt').value);
    if(!(a>0)){$('msg').textContent='Enter an amount above 0.';return}
    if(!$('date').value){$('msg').textContent='Pick a date.';return}
    items.push({id:Date.now()+Math.random(),desc:$('desc').value.trim()||$('cat').value,amt:a,cat:$('cat').value,date:$('date').value});
    $('msg').textContent='Added.';
    $('desc').value='';$('amt').value='';
    $('month').value=$('date').value.slice(0,7);
    save();render();
  }

  function render(){
    var m=$('month').value;
    var cur=items.filter(function(i){return i.date.slice(0,7)===m})
                 .sort(function(a,b){return b.date.localeCompare(a.date)});
    var sum=cur.reduce(function(s,i){return s+i.amt},0);
    $('total').textContent=inr(sum);
    $('count').textContent=cur.length+(cur.length===1?' entry':' entries')+' this month';

    var by={};
    cur.forEach(function(i){by[i.cat]=(by[i.cat]||0)+i.amt});
    var keys=Object.keys(by).sort(function(a,b){return by[b]-by[a]});
    $('cats').innerHTML=keys.length?keys.map(function(k){
      var p=sum?Math.round(by[k]/sum*100):0;
      return '<div class="cat"><span>'+esc(k)+'</span><span>'+inr(by[k])+' ('+p+'%)</span></div><div class="bar"><div style="width:'+p+'%"></div></div>';
    }).join(''):'<span class="muted">No spending yet for this month.</span>';

    $('list').innerHTML=cur.length?cur.map(function(i){
      return '<div class="item"><div>'+esc(i.desc)+'<div class="muted">'+esc(i.cat)+' · '+i.date+'</div></div><div>'+inr(i.amt)+' <button class="x" data-id="'+i.id+'">✕</button></div></div>';
    }).join(''):'';
  }

  $('add').addEventListener('click',add);
  $('amt').addEventListener('keydown',function(e){if(e.key==='Enter')add()});
  $('desc').addEventListener('keydown',function(e){if(e.key==='Enter')add()});
  $('month').addEventListener('change',render);
  $('list').addEventListener('click',function(e){
    var id=e.target.getAttribute&&e.target.getAttribute('data-id');
    if(!id)return;
    items=items.filter(function(i){return String(i.id)!==id});
    save();render();
  });
  render();
})();
</script>
</body>
</html>
```
